int start_dma_with_bch_irq ( struct gpmi_nand_data * this , struct dma_async_tx_descriptor * desc ) { struct completion * bch_c = & this -> bch_done ; init_completion ( bch_c ) ; start_dma_without_bch_irq ( this , desc ) ; timeout = wait_for_completion_timeout ( bch_c , msecs_to_jiffies ( 1000 ) ) ; if ( ! timeout ) { dev_err ( this -> dev , "BCH timeout, last DMA :%d\n" , this -> last_dma_type ) ; gpmi_dump_info ( this ) ; return - ETIMEDOUT ; } return 0 ; } 